insert into public.contacts(workspace_id,first_name,last_name,job_title,email,phone,status,notes,source_url,source_label,source_confidence,source_verified_at)
select o.workspace_id,'Ryan','Murphy','Asset Manager','rmurphy@huntingtonproperties.ca','613-592-1818 ext. 31','active','Current Huntington Properties staff directory. Asset Manager. Source: https://huntingtonproperties.ca/our-team/','https://huntingtonproperties.ca/our-team/','Huntington Properties official team directory','high',now()
