select p.workspace_id,p.id,c.id,'facilities_governance',false,false,'Elmwood leadership page identifies Simon Nehme as Board Vice-Chair and Chair of the Facilities Committee. Source: https://www.elmwood.ca/about/leadership'
from public.properties p join public.contacts c on c.workspace_id=p.workspace_id and c.first_name='Simon' and c.last_name='Nehme'
where p.workspace_id='431aa13d-3e7c-41e3-9686-e840b8ea5b7c' and p.owner_organization_id=(select id from public.organizations where workspace_id=p.workspace_id and coalesce(operating_name,legal_name)='Elmwood School') and not exists(select 1 from public.property_contacts x where x.property_id=p.id and x.contact_id=c.id);
